// ------------------------------------------------------------------ run
phase('Build')
log('Site tracks: home option B, film re-encode, follow-ups')
const siteTracks = parallel([
  () => agent(HOME_B, { label: 'site:home-option-b', phase: 'Build', schema: RESULT }),
  () => agent(FILM_ENCODE, { label: 'site:film-encode', phase: 'Build', schema: RESULT }),
  () => agent(SITE_FOLLOWUPS, { label: 'site:followups', phase: 'Build', schema: RESULT }),
]).then(([homeB, film, followups]) => ({ homeB, film, followups }))

log('Building student, parent, daily10 in parallel; tutor then school')

const builds = {
  student: () => agent(STUDENT, { label: 'build:student', phase: 'Build', schema: RESULT }),
  parent: () => agent(PARENT, { label: 'build:parent', phase: 'Build', schema: RESULT }),
  daily10: () => agent(DAILY10, { label: 'build:daily10', phase: 'Build', schema: RESULT }),
  tutor: () => agent(TUTOR, { label: 'build:tutor', phase: 'Build', schema: RESULT }),
}
const prompts = { student: STUDENT, parent: PARENT, daily10: DAILY10, tutor: TUTOR }

async function reviewFix(name, buildRes) {
  if (!buildRes) return { name, build: null, review: null, fix: null }
  const review = await agent(REVIEWER(name, buildRes), { label: `review:${name}`, phase: 'Review', schema: REVIEW })
  if (!review) return { name, build: buildRes, review: null, fix: null }
  const material = review.fixes.filter((f) => f.severity !== 'minor').length
  log(`${name}: review verdict ${review.verdict}, ${review.fixes.length} fixes (${material} material)`)
  if (review.verdict === 'ship' && material === 0) return { name, build: buildRes, review, fix: null }
  const fix = await agent(FIXER(name, prompts[name] || SCHOOL(null), review), { label: `fix:${name}`, phase: 'Fix and verify', schema: RESULT })
  return { name, build: buildRes, review, fix }
}

const results = await parallel([
  () => builds.student().then((r) => reviewFix('student', r)),
  () => builds.parent().then((r) => reviewFix('parent', r)),
  () => builds.daily10().then((r) => reviewFix('daily10', r)),
  () => builds.tutor().then(async (tutorRes) => {
    const t = reviewFix('tutor', tutorRes)
    const schoolRes = await agent(SCHOOL(tutorRes), { label: 'build:school', phase: 'Build', schema: RESULT })
    prompts.school = SCHOOL(tutorRes)
    const s = reviewFix('school', schoolRes)
    return { tutor: await t, school: await s }
  }),
])
const site = await siteTracks
log('Portals built, reviewed and fixed; site tracks finished')
return { portals: results, site }
